  const span = size === 'large' || rand() < 0.5 ? 100 : 12;
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * Math.min(8, span));
  const pool = Array.from({ length: span }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return [pool.slice(0, n)];
}
